#include<limits.h>
#include <assert.h>
#define N 100
#define fun bor

int unknown();
/*@
	assigns \nothing;
	ensure INT_MIN <= \result < INT_MAX;
*/

int bor (int x[N])
{
  int i, res;
  res = x[0];
  for (i = 1; i < N; i++) {
    res = res | x[i];
  }
  return res;
}
/*@
	requires \valid(x + (0..N-1));
	requires N == 100;
	ensure INT_MIN <= \result < INT_MAX;
*/

int main ()
{
  int x[N];
  int temp;
  int ret, ret2, ret5;
  for (int i = 0; i < N; i++) {
    x[i] = unknown();
  }
  ret = fun(x);
  temp=x[0];x[0] = x[1]; x[1] = temp;
  ret2 = fun(x);
  temp=x[0];
  for(int i =0 ; i<N-1; i++){
     x[i] = x[i+1];
  }
  x[N-1] = temp;
  ret5 = fun(x);
  //@ assert !(ret != ret2 || ret!=ret5);
  return 1;
}
